inline Record key(Domain d,std::size_t slot,std::uint64_t identity){return{slot*d.stride+identity,identity};}
template<class T>inline void finish_epoch(T& x){auto epoch=x.epoch();do{x.erase(key({UINT64_C(1)<<40,4096},4095,1));if(x.tree_buckets()>32)throw std::runtime_error("budget32 exceeded during engineering trajectory");}while(x.epoch()==epoch);}
template<class T>inline void heat_bucket(T& x,Domain d,std::size_t slot,std::uint64_t row,std::size_t times=256){for(std::size_t j=0;j<times;++j){auto out=x.range(slot*d.stride+row,slot*d.stride+row+1);if(out.size()!=1)throw std::runtime_error("legal heat full record");}x.erase(key(d,slot,UINT64_C(999999999)));finish_epoch(x);}
