  resource_log<<"API_ordinal,tree_buckets,persistent_requested_bytes,pool,buckets,tree,manager,whole_peak,snapshot_reason,engineering_only\n";for(std::size_t j=0;j<o.resource_size;++j){auto snap=o.resources[j];resource_log<<snap.api_ordinal<<','<<snap.trees<<','<<snap.persistent;for(auto bytes:snap.current)resource_log<<','<<bytes;resource_log<<','<<snap.whole_peak<<",conversion,true\n";}trajectory_log.close();if(!events||!samples||!resource_log)throw std::runtime_error("engineering evidence output failed");
  std::ofstream periodic(dir/"periodic_resource.csv");periodic<<"completed_units,API_ordinal,tree_buckets,persistent_requested_bytes,pool,buckets,tree,manager,whole_current,whole_peak,snapshot_reason_bits,output_released,engineering_only\n";for(auto snap:measured.resources){periodic<<snap.completed_units<<','<<snap.api_ordinal<<','<<snap.trees<<','<<snap.persistent;for(auto bytes:snap.current)periodic<<','<<bytes;periodic<<','<<snap.whole_current<<','<<snap.whole_peak<<','<<snap.reasons<<','<<snap.output_released<<",true\n";}if(!periodic)throw std::runtime_error("periodic resource evidence write failed");
